tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlasq4, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 16', function test( t ) {
	t.strictEqual( dlasq4.length, 16, 'returns expected value' );
	t.end();
});

tape( 'the function computes an approximation to the smallest eigenvalue using values of d from the previous transform (TTYPE=-1)', function test( t ) {
	var expected;
	var data;
	var out;
	var Z;

	data = TTYPE_1;

	Z = new Float64Array( data.Z );
	out = new Float64Array( [ 0, 0, data.G ] );

	expected = new Float64Array( data.expectedOut );

	dlasq4( data.I0, data.N0, Z, data.strideZ, data.offsetZ, data.PP, data.N0IN, data.DMIN, data.DMIN1, data.DMIN2, data.DN, data.DN1, data.DN2, out, data.strideOut, data.offsetOut );
	t.strictEqual( isAlmostEqual( out, expected, 1 ), true, 'returns expected value' );
	t.end();
});

